package com.featuredeliveryintelligence.fdi.runtime;import java.util.*;
public final class FeatureKnowledgePlan{private FeatureKnowledgePlan(){}public static List<Map<String,Object>>compile(Map<String,Object>plan,Map<String,Object>skill){String pid=RuntimeMaps.requiredString(plan,"plan_id"),sid=RuntimeMaps.requiredString(skill,"skill_id"),rev=RuntimeMaps.requiredString(skill,"skill_revision");if(!(plan.get("revision")instanceof Number))throw new RuntimeContractException("integer revision is required");Map<String,Map<String,Object>>templates=new HashMap<>();for(Object x:RuntimeMaps.list(skill,"context_requirement_templates")){Map<String,Object>t=map(x);templates.put(RuntimeMaps.requiredString(t,"template_id"),t);}List<Map<String,Object>>out=new ArrayList<>();for(Object x:RuntimeMaps.list(plan,"items")){Map<String,Object>i=map(x),t=templates.get(i.get("template_id"));if(t==null)throw new RuntimeContractException("unknown root requirement template");if(!Objects.equals(i.get("knowledge_role"),t.get("knowledge_role"))||!RuntimeMaps.list(t,"allowed_authority_dimensions").contains(i.get("authority_dimension")))throw new RuntimeContractException("FeatureKnowledgePlan exceeds root Skill authority");String mode=RuntimeMaps.requiredString(i,"mode");if(!RuntimeMaps.list(t,"allowed_modes").contains(mode)&&!("REQUIRED".equals(mode)&&Boolean.TRUE.equals(t.get("may_promote_to_required"))))throw new RuntimeContractException("mode is not permitted by root requirement template");Map<String,Object>r=new LinkedHashMap<>(i);r.put("root_skill_id",sid);r.put("root_skill_revision",rev);r.put("feature_knowledge_plan_id",pid);r.put("feature_knowledge_plan_revision",plan.get("revision"));r.put("root_requirement_template_id",i.get("template_id"));out.add(r);}return out;}@SuppressWarnings("unchecked")private static Map<String,Object>map(Object x){if(!(x instanceof Map<?,?>))throw new RuntimeContractException("item must be object");return(Map<String,Object>)x;}}
